/* HEXA BATTLEGROUNDS setup — PART 33 OF 57. Run parts in order. Safe to re-run. */ create or replace function _lock_next(p_arena uuid, p_building text default null, p_level int default null) returns uuid language plpgsql as $$ declare a arenas; v_b text; v_l int; v_id uuid; bb buildings; v_room text; v_warn int; begin select * into a from arenas where id = p_arena; if p_building is not null then v_b := p_building; v_l := p_level; else select t.building, t.level into v_b, v_l from _lock_targets() t where not exists (select 1 from lockdowns l where l.arena_id = p_arena and l.building = t.building and (l.level is null or l.level is not distinct from t.level)) limit 1; end if; if v_b is null then return null; end if; if v_b = 'hexavarsity' then raise exception 'HEXAVARSITY_NEVER_SEALS'; end if; select * into bb from buildings where id = v_b; if bb.id is null then raise exception 'BAD_BUILDING'; end if; if v_l is not null and (v_l < 0 or v_l >= bb.floors) then raise exception 'NO_FLOOR'; end if; if exists (select 1 from lockdowns l where l.arena_id = p_arena and l.building = v_b and (l.level is null or l.level is not distinct from v_l)) then return null; end if; v_warn := greatest(10, _cfg(a.event_id, 'lock_warning')); insert into lockdowns(arena_id, building, level, seal_at) values (p_arena, v_b, v_l, now() + _secs(v_warn)) returning id into v_id; update arenas set last_lock_at = now() where id = p_arena; select l.id into v_room from locations l where l.enabled and l.building = v_b and l.kind not in ('stairs', 'start') and (v_l is null or l.level = v_l) and not exists (select 1 from airdrops ad where ad.arena_id = p_arena and ad.location_id = l.id and ad.status = 'open') order by l.level desc, random() limit 1; if v_room is not null then perform _spawn_vault(p_arena, v_room, now() + _secs(v_warn)); end if; perform _feed(p_arena, 'lockdown.warning', jsonb_build_object('building', v_b, 'name', bb.name, 'level', v_l, 'seconds', v_warn, 'vault', v_room)); perform _lock_publish(p_arena); return v_id; end $$; create or replace function _lock_seal(p_lock uuid) returns void language plpgsql as $$ declare l lockdowns; a arenas; b buildings; tm teams; xy float8[]; v_inside boolean; v_heading boolean; v_nums int[] := '{}'; begin select * into l from lockdowns where id = p_lock for update; if l.id is null or l.sealed then return; end if; select * into a from arenas where id = l.arena_id; select * into b from buildings where id = l.building; update lockdowns set sealed = true, sealed_at = now() where id = l.id; for tm in select * from teams where arena_id = l.arena_id and ready loop xy := _team_xy(tm); if l.level is null then v_inside := (tm.level > 0 and tm.bldg = b.id) or (tm.level = 0 and tm.state <> 'traveling' and xy[1] between b.x0 and b.x1 and xy[2] between b.y0 and b.y1); v_heading := tm.state = 'traveling' and exists (select 1 from locations where id = tm.travel_to and building = b.id); else v_inside := tm.level = l.level and tm.bldg = b.id; v_heading := tm.state = 'traveling' and exists (select 1 from locations where id = tm.travel_to and building = b.id and level = l.level); end if; if v_inside then update mission_instances set status = 'cancelled' where team_id = tm.id and status = 'active' and kind in ('mission', 'relay', 'airdrop') and sync_round_id is null; update teams set level = 0, bldg = null, pos_x = b.door_x, pos_y = b.door_y, pos_at = now(), vel_x = 0, vel_y = 0, location_id = null, visit_missions = 0 where id = tm.id; perform _damage(tm.id, _cfg(a.event_id, 'lock_damage'), 'lockdown', l.id::text, 'Caught inside a lockdown'); v_nums := v_nums || tm.number; perform _ping_team(tm.id, 'lockdown'); elsif v_heading then update teams set state = 'idle', pos_x = xy[1], pos_y = xy[2], pos_at = now(), vel_x = 0, vel_y = 0, travel_to = null, travel_from = null, travel_started_at = null, travel_arrive_at = null, travel_fx = null, travel_fy = null where id = tm.id; perform _ping_team(tm.id, 'lockdown'); end if; end loop; update lockdowns set caught = coalesce(array_length(v_nums, 1), 0) where id = l.id; delete from pickups where arena_id = l.arena_id and taken_at is null and ((bldg = b.id and (l.level is null or level = l.level)) or (l.level is null and level = 0 and x between b.x0 and b.x1 and y between b.y0 and b.y1)); update airdrops set status = 'expired' where arena_id = l.arena_id and status = 'open' and location_id in (select id from locations where building = b.id and (l.level is null or level = l.level)); update mission_instances mi set status = 'cancelled' from airdrops ad where mi.airdrop_id = ad.id and ad.status = 'expired' and mi.status = 'active'; perform _feed(l.arena_id, 'lockdown.sealed', jsonb_build_object('building', b.id, 'name', b.name, 'level', l.level, 'caught', to_jsonb(v_nums))); perform _lock_publish(l.arena_id); end $$; create or replace function _final_lockdown(p_arena uuid) returns void language plpgsql as $$ declare r record; begin for r in select id from buildings where id <> 'hexavarsity' loop if not exists (select 1 from lockdowns where arena_id = p_arena and building = r.id and level is null) then insert into lockdowns(arena_id, building, level, seal_at) values (p_arena, r.id, null, now()); end if; end loop; for r in select id from lockdowns where arena_id = p_arena and not sealed loop perform _lock_seal(r.id); end loop; update arenas set finale_stage = 'D' where id = p_arena and phase = 'finale'; if not exists (select 1 from story_events where arena_id = p_arena and kind = 'reveal') then insert into story_events(arena_id, kind, title, body) values (p_arena, 'reveal', 'Final lockdown', 'Every building on campus is sealed except Hexavarsity. Training Room 14 is the last open room.'); end if; perform _feed(p_arena, 'lockdown.final', '{}'::jsonb); perform _lock_publish(p_arena); end $$; create or replace function _spawn_pickups(p_arena uuid) returns int language plpgsql as $$ declare a arenas; k text; v_want int; v_have int; v_n int := 0; l locations; b buildings; ang float8; rad float8; px float8; py float8; v_try int; begin select * into a from arenas where id = p_arena; foreach k in array array['medkit', 'shield', 'coins'] loop v_want := coalesce(_cfg(a.event_id, 'pickup_' || k), 0); select count(*) into v_have from pickups where arena_id = p_arena and taken_at is null and kind = k; v_try := 0; while v_have < v_want and v_try < v_want * 3 loop v_try := v_try + 1; select * into l from locations loc where loc.enabled and loc.kind not in ('start', 'stairs') and not (loc.building is not null and _sealed(p_arena, loc.building, loc.level)) order by random() limit 1; exit when l.id is null; ang := random() * 2 * pi(); rad := 0.008 + random() * 0.014; px := l.x + cos(ang) * rad; py := l.y + sin(ang) * rad; if l.level > 0 then select * into b from buildings where id = l.building; px := greatest(b.x0 + 0.006, least(b.x1 - 0.006, px)); py := greatest(b.y0 + 0.006, least(b.y1 - 0.006, py)); end if; insert into pickups(arena_id, kind, x, y, level, bldg) values (p_arena, k, greatest(0.02, least(0.98, px)), greatest(0.02, least(0.98, py)), l.level, case when l.level > 0 then l.building end); v_have := v_have + 1; v_n := v_n + 1; end loop; end loop; update arenas set last_pickup_at = now() where id = p_arena; return v_n; end $$; create or replace function _take_pickups(p_team uuid, p_x float8, p_y float8) returns jsonb language plpgsql as $$ declare t teams; pk pickups; v_out jsonb := '[]'::jsonb; v_med int; begin select * into t from teams where id = p_team; for pk in select * from pickups where arena_id = t.arena_id and taken_at is null and level = t.level and (x - p_x) ^ 2 + (y - p_y) ^ 2 <= 0.013 ^ 2 for update skip locked loop select coalesce(qty, 0) into v_med from inventory where team_id = t.id and item_id = 'medkit'; if pk.kind = 'medkit' and coalesce(v_med, 0) >= 5 then continue; end if; if pk.kind = 'shield' and t.shield >= _cfg(t.event_id, 'shield_max') then continue; end if; update pickups set taken_by = t.id, taken_at = now() where id = pk.id; if pk.kind = 'medkit' then perform _add_item(t.id, 'medkit', 1); elsif pk.kind = 'shield' then update teams set shield = least(_cfg(t.event_id, 'shield_max'), shield + 20) where id = t.id returning * into t; else perform _apply(t.id, 'pickup', 0, 15, 0, 0, pk.id::text, 'Picked up a coin stack'); end if; v_out := v_out || jsonb_build_array(pk.kind); end loop; if jsonb_array_length(v_out) = 0 then return null; end if; perform _ping_arena(t.arena_id, 'pickup'); return v_out; end $$; create or replace function captain_stairs(p_token text, p_dir int) returns jsonb language plpgsql security definer set search_path = public as $$ declare p players; t teams; a arenas; b buildings; cur float8[]; v_new int; v_loc text; begin p := _auth_captain(p_token); select * into t from teams where id = p.team_id for update; select * into a from arenas where id = t.arena_id; if a.phase <> 'play' then raise exception 'NO_MOVES_NOW'; end if; if t.state in ('recovery', 'traveling') then raise exception 'BUSY'; end if; if exists (select 1 from mission_instances where team_id = t.id and status = 'active' and kind = 'battle') then raise exception 'IN_BATTLE'; end if; if p_dir is null or p_dir not in (-1, 1) then raise exception 'BAD_REQUEST'; end if; cur := _team_xy(t); if t.level > 0 then select * into b from buildings where id = t.bldg; else select * into b from buildings where floors > 1 order by (stair_x - cur[1]) ^ 2 + (stair_y - cur[2]) ^ 2 limit 1; end if; if b.id is null or (b.stair_x - cur[1]) ^ 2 + (b.stair_y - cur[2]) ^ 2 > 0.018 ^ 2 then raise exception 'NOT_AT_STAIRS'; end if; v_new := t.level + p_dir; if v_new < 0 or v_new >= b.floors then raise exception 'NO_FLOOR'; end if; if _sealed(t.arena_id, b.id, v_new) then raise exception 'SEALED'; end if; update mission_instances set status = 'cancelled' where team_id = t.id and status = 'active' and kind in ('mission', 'relay', 'airdrop') and sync_round_id is null; v_loc := _loc_at3(t.arena_id, t.event_id, b.stair_x, b.stair_y, v_new, b.id); update teams set level = v_new, bldg = case when v_new > 0 then b.id end, pos_x = b.stair_x, pos_y = b.stair_y, pos_at = now(), vel_x = 0, vel_y = 0, location_id = v_loc, visit_missions = 0, dropped = true, state = 'idle' where id = t.id; perform _ping_team(t.id, 'stairs'); return jsonb_build_object('level', v_new, 'building', b.id, 'location', v_loc, 'x', b.stair_x, 'y', b.stair_y); end $$; create or replace function arena_positions(p_token text) returns jsonb language plpgsql security definer set search_path = public as $$ declare p players; t teams; v_scan boolean; begin p := _auth_player(p_token); select * into t from teams where id = p.team_id; v_scan := t.scan_until is not null and t.scan_until > now(); return jsonb_build_object('server_now', now(), 'squads', (select coalesce(jsonb_agg(jsonb_build_object( 'id', tm.id, 'level', tm.level, 'bldg', tm.bldg, 'state', tm.state, 'pos', to_jsonb(_team_xy(tm)), 'vel', case when tm.state = 'traveling' and tm.travel_arrive_at > now() and l.id is not null then jsonb_build_array((l.x - coalesce(tm.travel_fx, l.x)) / greatest(0.2, extract(epoch from tm.travel_arrive_at - tm.travel_started_at)), (l.y - coalesce(tm.travel_fy, l.y)) / greatest(0.2, extract(epoch from tm.travel_arrive_at - tm.travel_started_at))) when tm.state = 'idle' and tm.pos_at > now() - interval '1500 milliseconds' then jsonb_build_array(tm.vel_x, tm.vel_y) end)), '[]'::jsonb) from teams tm left join locations l on l.id = tm.travel_to where tm.arena_id = t.arena_id and tm.ready and (tm.id = t.id or v_scan or tm.location_id = t.location_id or tm.jammed_until is null or tm.jammed_until < now() or exists (select 1 from alliances al where al.status = 'active' and ((al.team_a = t.id and al.team_b = tm.id) or (al.team_b = t.id and al.team_a = tm.id)))))); end $$; create or replace function _spawn_start_vaults(p_arena uuid) returns void language plpgsql as $$ declare a arenas; r record; begin select * into a from arenas where id = p_arena; for r in select l.id from locations l where l.enabled and l.level >= 2 and l.kind = 'room' and l.building <> 'hexavarsity' order by random() limit greatest(0, coalesce(_cfg(a.event_id, 'vaults'), 2)) loop perform _spawn_vault(p_arena, r.id, now() + interval '40 minutes'); end loop; end $$; create or replace function _defaults() returns jsonb language sql immutable as $$ select jsonb_build_object( 'pts_standard', 100, 'pts_hard', 150, 'pts_battle', 125, 'pts_airdrop', 75, 'pts_relay_bonus', 25, 'pts_relocation', 40, 'pen_recovery', 40, 'finale_max', 300, 'finale_entry_max', 200, 'finale_exchange_max', 200, 'hp_max', 100, 'hp_respawn', 50, 'dmg_fail', 20, 'dmg_zone', 15, 'shield_max', 60, 'shuttle_seconds', 10, 'roles_seconds', 15, 'bus_size', 3, 'arena_size', 15, 'attack_cooldown', 90, 'protect_seconds', 120, 'recovery_seconds', 120, 'zone_warning', 60, 'airdrop_window', 180, 'airdrop_interval', 0, 'intel_fallback', 90, 'relay_chance', 20, 'hint_cost', 0, 'alliance_minutes', 10, 'alliance_cost', 10, 'chat_limit', 6, 'drop_seconds', 8, 'visit_missions', 2, 'zone_auto', 0, 'zone_schedule', '20,40,55,70,85', 'sync_seconds', 0, 'auto_pacing', 0, 'phase_schedule', '2,12,30,50', 'duel_phase', 2, 'mission_time_pct', 100, 'pin_length', 6, 'move_speed', 16, 'loc_radius', 18, 'engage_range', 40, 'zone_tick_seconds', 6, 'zone_tick_damage', 4, 'red_interval', 0, 'red_warning', 20, 'red_damage', 30, 'red_radius', 80 ) || jsonb_build_object( 'reveal_pct', 50, 'boarding_seconds', 18, 'finale_minute', 0, 'finale_battles', 2, 'dmg_wrong', 5, 'dmg_airdrop_fail', 10, 'lock_interval', 150, 'lock_warning', 45, 'lock_damage', 30, 'pickup_medkit', 16, 'pickup_shield', 8, 'pickup_coins', 12, 'pickup_respawn', 75, 'vaults', 2 ) $$; create or replace function _auto_preset(p_length text) returns jsonb language sql immutable as $$ select case coalesce(p_length, 'standard') when 'quick' then jsonb_build_object('auto_pacing', 1, 'phase_schedule', '1,3,5,7', 'finale_minute', 9, 'finale_battles', 1, 'zone_warning', 25, 'airdrop_interval', 1, 'red_interval', 2, 'mission_time_pct', 70, 'shuttle_seconds', 12, 'roles_seconds', 12, 'sync_seconds', 90, 'recovery_seconds', 45, 'attack_cooldown', 45, 'protect_seconds', 45, 'boarding_seconds', 12, 'airdrop_window', 90, 'lock_interval', 55, 'lock_warning', 30, 'pickup_respawn', 45) when 'full' then jsonb_build_object('auto_pacing', 1, 'phase_schedule', '3,15,30,45', 'finale_minute', 55, 'finale_battles', 3, 'zone_warning', 60, 'airdrop_interval', 5, 'red_interval', 6, 'mission_time_pct', 100, 'shuttle_seconds', 20, 'roles_seconds', 15, 'sync_seconds', 0, 'recovery_seconds', 120, 'attack_cooldown', 90, 'protect_seconds', 120, 'boarding_seconds', 25, 'airdrop_window', 180, 'lock_interval', 210, 'lock_warning', 50, 'pickup_respawn', 90) else jsonb_build_object('auto_pacing', 1, 'phase_schedule', '2,6,11,16', 'finale_minute', 21, 'finale_battles', 2, 'zone_warning', 40, 'airdrop_interval', 3, 'red_interval', 4, 'mission_time_pct', 85, 'shuttle_seconds', 15, 'roles_seconds', 15, 'sync_seconds', 120, 'recovery_seconds', 75, 'attack_cooldown', 60, 'protect_seconds', 75, 'boarding_seconds', 18, 'airdrop_window', 120, 'lock_interval', 100, 'lock_warning', 40, 'pickup_respawn', 60) end $$; create or replace function _auto_step_name(p_pos int, p_n int) returns text language sql immutable as $$ select case when p_pos <= 0 then 'Finale entry round' when p_pos = 1 then 'Exchange round' when p_pos <= 1 + p_n then 'Finale battle ' || p_pos when p_pos = 2 + p_n then 'Final lockdown' when p_pos = 3 + p_n then 'Final code' when p_pos = 4 + p_n then 'Results locked' when p_pos = 5 + p_n then 'Winner reveal' when p_pos = 6 + p_n then 'Grand champion' else 'Match complete' end $$;
